#include <vector>
using namespace std;

class Solution {
public:
    int atMostK(vector<int>& nums, int k) {
        int i = 0, count = 0;
        for (int j = 0; j < nums.size(); j++) {
            k -= nums[j] % 2;
            while (k < 0) {
                k += nums[i] % 2;
                i++;
            }
            count += j - i + 1;
        }
        return count;
    }

    int numberOfSubarrays(vector<int>& nums, int k) {
        return atMostK(nums, k) - atMostK(nums, k - 1);
    }
};
